diff --git a/CSR_FlengthCluster.h b/CSR_FlengthCluster.h
index 97f4427..49847da 100644
--- a/CSR_FlengthCluster.h
+++ b/CSR_FlengthCluster.h
@@ -2,21 +2,51 @@
 #define _CSR_FLENGTH_CLUSTER_H_

 #include <stdexcept>
+#include <utility>
 #include "CSR.h"
+#include "frontier_solution/fcs_util.h"
+#include "frontier_solution/fcs_build.h"

+// Fixed-length clustered CSR: every group of `cluster_sz` consecutive rows
+// shares one ascending list of column indices (the union of its rows), and
+// each stored column keeps `cluster_sz` lane values (lane k = row g*cs + k).
 template<class IT, class NT>
 class CSR_FlengthCluster {
 public:
   CSR_FlengthCluster() : csr_rows(0), rows(0), cols(0), cluster_sz(0), nnzc(0), rowptr(nullptr), colids(nullptr), values(nullptr) {}
-  CSR_FlengthCluster(const CSR<IT, NT> &, IT) : CSR_FlengthCluster() {
-    throw std::logic_error("CSR_FlengthCluster is not implemented");
+  CSR_FlengthCluster(const CSR<IT, NT> &A, IT cluster_size) : CSR_FlengthCluster() {
+    try {
+      fcs::build_flength_cluster(A, cluster_size, *this);
+    } catch (...) {
+      make_empty();
+      throw;
+    }
   }
+  CSR_FlengthCluster(const CSR_FlengthCluster &rhs) : CSR_FlengthCluster() { copy_from(rhs); }
+  CSR_FlengthCluster(CSR_FlengthCluster &&rhs) noexcept : CSR_FlengthCluster() { swap(rhs); }
+  CSR_FlengthCluster &operator=(const CSR_FlengthCluster &rhs) {
+    if (this != &rhs) {
+      make_empty();
+      copy_from(rhs);
+    }
+    return *this;
+  }
+  CSR_FlengthCluster &operator=(CSR_FlengthCluster &&rhs) noexcept {
+    if (this != &rhs) {
+      make_empty();
+      swap(rhs);
+    }
+    return *this;
+  }
+
   void make_empty() {
-    if (rowptr) my_free<IT>(rowptr);
-    if (colids) my_free<IT>(colids);
-    if (values) my_free<NT>(values);
-    rowptr = nullptr; colids = nullptr; values = nullptr;
+    release(rowptr, mb_rowptr);
+    release(colids, mb_colids);
+    release(values, mb_values);
+    fcs::mem_free(mb_alive);
+    alive = nullptr;
     csr_rows = rows = cols = cluster_sz = nnzc = 0;
+    zero_entries = -1;
   }
   ~CSR_FlengthCluster() { make_empty(); }
   bool isEmpty() { return nnzc == 0; }
@@ -24,6 +54,50 @@ public:
   IT csr_rows, rows, cols, cluster_sz, nnzc;
   IT *rowptr, *colids;
   NT *values;
+
+  // Allocation bookkeeping for the arrays above.
+  fcs::MemBlock mb_rowptr, mb_colids, mb_values;
+  // Number of stored entries whose lanes are all exactly zero (-1: unknown),
+  // and per-entry flags (1 = some lane nonzero) when zero entries exist.
+  int64_t zero_entries = -1;
+  unsigned char *alive = nullptr;
+  fcs::MemBlock mb_alive;
+
+private:
+  template <class T>
+  static void release(T *&p, fcs::MemBlock &mb) {
+    if (p && mb.base != (void *)p) my_free<T>(p);  // array installed by someone else
+    fcs::mem_free(mb);
+    p = nullptr;
+  }
+  void swap(CSR_FlengthCluster &o) noexcept {
+    std::swap(csr_rows, o.csr_rows); std::swap(rows, o.rows); std::swap(cols, o.cols);
+    std::swap(cluster_sz, o.cluster_sz); std::swap(nnzc, o.nnzc);
+    std::swap(rowptr, o.rowptr); std::swap(colids, o.colids); std::swap(values, o.values);
+    std::swap(mb_rowptr, o.mb_rowptr); std::swap(mb_colids, o.mb_colids); std::swap(mb_values, o.mb_values);
+    std::swap(zero_entries, o.zero_entries);
+    std::swap(alive, o.alive); std::swap(mb_alive, o.mb_alive);
+  }
+  void copy_from(const CSR_FlengthCluster &o) {
+    csr_rows = o.csr_rows; rows = o.rows; cols = o.cols; cluster_sz = o.cluster_sz; nnzc = o.nnzc;
+    zero_entries = o.zero_entries;
+    if (o.alive) {
+      alive = (unsigned char *)fcs::mem_alloc((size_t)std::max<IT>(nnzc, 1), mb_alive);
+      std::copy(o.alive, o.alive + nnzc, alive);
+    }
+    if (o.rowptr) {
+      rowptr = (IT *)fcs::mem_alloc(sizeof(IT) * (size_t)(rows + 1), mb_rowptr);
+      std::copy(o.rowptr, o.rowptr + rows + 1, rowptr);
+    }
+    if (o.colids) {
+      colids = (IT *)fcs::mem_alloc(sizeof(IT) * (size_t)std::max<IT>(nnzc, 1), mb_colids);
+      std::copy(o.colids, o.colids + nnzc, colids);
+    }
+    if (o.values) {
+      values = (NT *)fcs::mem_alloc(sizeof(NT) * (size_t)std::max<IT>(nnzc, 1) * (size_t)cluster_sz, mb_values);
+      std::copy(o.values, o.values + (size_t)nnzc * cluster_sz, values);
+    }
+  }
 };

 #endif
