 #ifndef CLUSTER_UTILITY_H
 #define CLUSTER_UTILITY_H
+#include <vector>
+#include <algorithm>
 #include "CSR.h"
 #include "CSR_FlengthCluster.h"

-// Compatibility declaration only; the conversion implementation is absent.
+// Expand a fixed-length clustered matrix into scalar CSR (nonzero lanes only,
+// column indices sorted within each row).
 template<class IT, class NT>
 void csr_flength_cluster2csr(
     CSR<IT, NT> &csr,
-    const CSR_FlengthCluster<IT, NT> &csr_flength_cluster);
+    const CSR_FlengthCluster<IT, NT> &cf) {
+  csr.make_empty();
+  const IT cs = cf.cluster_sz;
+  const IT nrows = cf.csr_rows;
+  std::vector<IT> cnt((size_t)nrows + 1, 0);
+#pragma omp parallel for schedule(dynamic, 64)
+  for (IT g = 0; g < cf.rows; ++g)
+    for (IT j = cf.rowptr[g]; j < cf.rowptr[g + 1]; ++j)
+      for (IT l = 0; l < cs; ++l)
+        if (cf.values[(size_t)j * cs + l] != NT(0)) ++cnt[(size_t)g * cs + l];
+  csr.rows = nrows;
+  csr.cols = cf.cols;
+  csr.zerobased = true;
+  csr.rowptr = my_malloc<IT>(nrows + 1);
+  IT s = 0;
+  for (IT r = 0; r < nrows; ++r) { csr.rowptr[r] = s; s += cnt[r]; }
+  csr.rowptr[nrows] = s;
+  csr.nnz = s;
+  if (s > 0) {
+    csr.colids = my_malloc<IT>(s);
+    csr.values = my_malloc<NT>(s);
+  }
+#pragma omp parallel for schedule(dynamic, 64)
+  for (IT g = 0; g < cf.rows; ++g) {
+    std::vector<std::pair<IT, NT>> row;
+    for (IT l = 0; l < cs; ++l) {
+      row.clear();
+      for (IT j = cf.rowptr[g]; j < cf.rowptr[g + 1]; ++j) {
+        const NT v = cf.values[(size_t)j * cs + l];
+        if (v != NT(0)) row.push_back(std::make_pair(cf.colids[j], v));
+      }
+      std::sort(row.begin(), row.end());
+      IT o = csr.rowptr[(size_t)g * cs + l];
+      for (auto &p : row) { csr.colids[o] = p.first; csr.values[o] = p.second; ++o; }
+    }
+  }
+  csr.is_sorted = true;
+  csr.is_value_sorted = false;
+}
 #endif
diff --git a/frontier_solution/fcs_build.h b/frontier_solution/fcs_build.h
new file mode 100644
index 0000000..507013e
--- /dev/null
+++ b/frontier_solution/fcs_build.h
@@ -0,0 +1,210 @@
+#ifndef FCS_BUILD_H
+#define FCS_BUILD_H
+
+// CSR -> fixed-length cluster conversion.  Each group of `cs` consecutive rows
+// stores the ascending union of its column indices and, per union entry, `cs`
+// lane values (missing lanes are zero).
+
+#include <vector>
+#include <algorithm>
+#include <utility>
+#include "fcs_util.h"
+#ifdef FCS_PROFILE
+#include <cstdio>
+#endif
+
+namespace fcs {
+
+// Merge the sorted rows [r0, r1) of a CSR into their ascending column union.
+// With FILL, writes union columns to oc and lane values to ov (pre-zeroed).
+// Returns the union size.  Duplicate columns within a row are summed.
+template <bool FILL, class IT, class NT>
+inline IT merge_rows(const IT *rp, const IT *ci, const NT *vv, IT r0, IT r1, IT cs,
+                     IT *oc, NT *ov, IT *pos, IT *end) {
+  const IT nl = r1 - r0;
+  IT active = 0;
+  for (IT l = 0; l < nl; ++l) {
+    pos[l] = rp[r0 + l];
+    end[l] = rp[r0 + l + 1];
+    if (pos[l] < end[l]) ++active;
+  }
+  if (active == 0) return 0;
+  if (active == 1) {  // single non-empty row: copy (deduplicating) directly
+    IT l = 0;
+    while (pos[l] >= end[l]) ++l;
+    IT cnt = 0, last = -1;
+    for (IT j = pos[l]; j < end[l]; ++j) {
+      const IT c = ci[j];
+      if (c != last) {
+        if (FILL) {
+          oc[cnt] = c;
+          ov[(size_t)cnt * cs + l] = vv[j];
+        }
+        ++cnt;
+        last = c;
+      } else if (FILL) {
+        ov[(size_t)(cnt - 1) * cs + l] += vv[j];
+      }
+    }
+    return cnt;
+  }
+  IT cnt = 0;
+  IT last = -1;
+  for (;;) {
+    IT m = -1;
+    bool any = false;
+    for (IT l = 0; l < nl; ++l) {
+      if (pos[l] < end[l]) {
+        const IT c = ci[pos[l]];
+        if (!any || c < m) m = c;
+        any = true;
+      }
+    }
+    if (!any) break;
+    if (m != last) {
+      if (FILL) oc[cnt] = m;
+      ++cnt;
+      last = m;
+    }
+    for (IT l = 0; l < nl; ++l) {
+      if (pos[l] < end[l] && ci[pos[l]] == m) {
+        if (FILL) {
+          NT &dst = ov[(size_t)(cnt - 1) * cs + l];
+          dst = dst + vv[pos[l]];
+        }
+        ++pos[l];
+      }
+    }
+  }
+  return cnt;
+}
+
+// Fallback for groups containing unsorted rows: sort (col, lane, val) records.
+template <bool FILL, class IT, class NT>
+inline IT merge_rows_unsorted(const IT *rp, const IT *ci, const NT *vv, IT r0, IT r1, IT cs,
+                              IT *oc, NT *ov) {
+  struct Rec { IT c; IT l; NT v; };
+  std::vector<Rec> recs;
+  for (IT r = r0; r < r1; ++r)
+    for (IT j = rp[r]; j < rp[r + 1]; ++j) recs.push_back(Rec{ci[j], r - r0, vv[j]});
+  std::stable_sort(recs.begin(), recs.end(), [](const Rec &x, const Rec &y) { return x.c < y.c; });
+  IT cnt = 0, last = -1;
+  for (const Rec &rc : recs) {
+    if (rc.c != last) {
+      if (FILL) oc[cnt] = rc.c;
+      ++cnt;
+      last = rc.c;
+    }
+    if (FILL) {
+      NT &dst = ov[(size_t)(cnt - 1) * cs + rc.l];
+      dst = dst + rc.v;
+    }
+  }
+  return cnt;
+}
+
+template <class IT>
+inline bool rows_sorted(const IT *rp, const IT *ci, IT r0, IT r1) {
+  for (IT r = r0; r < r1; ++r)
+    for (IT j = rp[r] + 1; j < rp[r + 1]; ++j)
+      if (ci[j] < ci[j - 1]) return false;
+  return true;
+}
+
+// Build `out` (a CSR_FlengthCluster-like object with MemBlock members).
+template <class CSRT, class OUT, class IT>
+void build_flength_cluster(const CSRT &A, IT cs, OUT &out) {
+  typedef typename std::remove_pointer<decltype(A.values)>::type NT;
+#ifdef FCS_PROFILE
+  const double bt0 = omp_get_wtime();
+#endif
+  if (cs <= 0) throw std::invalid_argument("cluster size must be positive");
+  const IT nr = A.rows;
+  const IT ng = (nr + cs - 1) / cs;
+  out.cluster_sz = cs;
+  out.csr_rows = ng * cs;
+  out.rows = ng;
+  out.cols = A.cols;
+  out.rowptr = (IT *)mem_alloc(sizeof(IT) * (size_t)(ng + 1), out.mb_rowptr);
+  const IT *rp = A.rowptr;
+  const IT *ci = A.colids;
+  const NT *vv = A.values;
+  const bool have_nz = (A.nnz > 0);
+
+  // Mark groups whose rows are not sorted (handled by the record fallback).
+  std::vector<unsigned char> unsorted;
+  bool any_unsorted = false;
+  if (have_nz && !A.is_sorted) {
+    unsorted.assign((size_t)ng, 0);
+#pragma omp parallel for schedule(static) reduction(|| : any_unsorted)
+    for (IT g = 0; g < ng; ++g) {
+      const IT r0 = g * cs, r1 = std::min(nr, r0 + cs);
+      if (!rows_sorted(rp, ci, r0, r1)) {
+        unsorted[g] = 1;
+        any_unsorted = true;
+      }
+    }
+  }
+
+  const IT chunk = std::max<IT>(16, std::min<IT>(4096, ng / (omp_get_max_threads() * 16 + 1)) & ~IT(7));
+  // Pass 1: union sizes.
+#pragma omp parallel
+  {
+    std::vector<IT> pos(cs), end(cs);
+#pragma omp for schedule(dynamic, chunk)
+    for (IT g = 0; g < ng; ++g) {
+      IT cnt = 0;
+      if (have_nz) {
+        const IT r0 = g * cs, r1 = std::min(nr, r0 + cs);
+        if (any_unsorted && unsorted[g])
+          cnt = merge_rows_unsorted<false, IT, NT>(rp, ci, vv, r0, r1, cs, nullptr, nullptr);
+        else
+          cnt = merge_rows<false, IT, NT>(rp, ci, vv, r0, r1, cs, nullptr, nullptr, pos.data(), end.data());
+      }
+      out.rowptr[g] = cnt;
+    }
+  }
+  const IT nnzc = exclusive_scan<IT>(out.rowptr, ng);
+  out.nnzc = nnzc;
+#ifdef FCS_PROFILE
+  const double bt1 = omp_get_wtime();
+#endif
+  out.colids = (IT *)mem_alloc(sizeof(IT) * (size_t)std::max<IT>(nnzc, 1), out.mb_colids);
+  out.values = (NT *)mem_alloc(sizeof(NT) * (size_t)std::max<IT>(nnzc, 1) * (size_t)cs, out.mb_values);
+
+  // Pass 2: fill columns and lane values; flag entries whose lanes are all zero.
+  out.alive = (unsigned char *)mem_alloc((size_t)std::max<IT>(nnzc, 1), out.mb_alive);
+  int64_t zero_entries = 0;
+#pragma omp parallel reduction(+ : zero_entries)
+  {
+    std::vector<IT> pos(cs), end(cs);
+#pragma omp for schedule(dynamic, chunk)
+    for (IT g = 0; g < ng; ++g) {
+      const IT o0 = out.rowptr[g], o1 = out.rowptr[g + 1];
+      if (o1 == o0) continue;
+      NT *ov = out.values + (size_t)o0 * cs;
+      std::fill(ov, ov + (size_t)(o1 - o0) * cs, NT(0));
+      const IT r0 = g * cs, r1 = std::min(nr, r0 + cs);
+      if (any_unsorted && unsorted[g])
+        merge_rows_unsorted<true, IT, NT>(rp, ci, vv, r0, r1, cs, out.colids + o0, ov);
+      else
+        merge_rows<true, IT, NT>(rp, ci, vv, r0, r1, cs, out.colids + o0, ov, pos.data(), end.data());
+      unsigned char *al = out.alive + o0;
+      for (IT j = 0; j < o1 - o0; ++j) {
+        bool z = true;
+        for (IT l = 0; l < cs; ++l) z &= (ov[(size_t)j * cs + l] == NT(0));
+        al[j] = z ? 0 : 1;
+        zero_entries += z;
+      }
+    }
+  }
+  out.zero_entries = zero_entries;
+#ifdef FCS_PROFILE
+  const double bt2 = omp_get_wtime();
+  fprintf(stderr, "  [build] count=%.4f fill=%.4f nnzc=%ld zero_entries=%ld\n", bt1 - bt0, bt2 - bt1, (long)nnzc, (long)zero_entries);
+#endif
+}
+
+}  // namespace fcs
+
+#endif
diff --git a/frontier_solution/fcs_spgemm.h b/frontier_solution/fcs_spgemm.h
new file mode 100644
index 0000000..8a9e2a8
--- /dev/null
+++ b/frontier_solution/fcs_spgemm.h
@@ -0,0 +1,782 @@
+#ifndef FCS_SPGEMM_H
+#define FCS_SPGEMM_H
+
+// Clustered hash SpGEMM: C(group) = A(group) * B with the ordered clustered
+// arithmetic of the original path:
+//   * union columns k of a group are visited in ascending order, and the
+//     stored columns of B[k,:] in their stored order;
+//   * the first path to an output column initializes every lane to a*b;
+//   * later paths add a*b to a lane only when |a| >= float(1e-6).
+// Two phases: a symbolic pass counts the distinct output columns of every
+// group, then a numeric pass accumulates directly into the final arrays.
+
+#include <cmath>
+#include <functional>
+#include <type_traits>
+#include <vector>
+#include <algorithm>
+#include <immintrin.h>
+#include "fcs_util.h"
+
+#ifdef FCS_PROFILE
+#include <cstdio>
+#define FCS_T(name) double name = omp_get_wtime()
+#else
+#define FCS_T(name)
+#endif
+
+namespace fcs {
+
+static const double kThrD = (double)0.000001f;  // 9.999999974752427e-7
+
+template <class K> struct KeyTraits;
+template <> struct KeyTraits<uint32_t> {
+  static inline size_t slot(uint32_t key, int shift) { return (uint32_t)(key * 0x9E3779B1u) >> shift; }
+  static const int bits = 32;
+};
+template <> struct KeyTraits<uint64_t> {
+  static inline size_t slot(uint64_t key, int shift) { return (size_t)((key * 0x9E3779B97F4A7C15ull) >> shift); }
+  static const int bits = 64;
+};
+
+// Per-thread all-zero bitmaps; users must leave them zeroed after use, so the
+// memset only happens when a bitmap is (re)allocated.
+inline uint64_t *clean_bitmap(int slot, size_t words) {
+  struct Bm {
+    uint64_t *p = nullptr;
+    size_t words = 0;
+    ~Bm() { free(p); }
+  };
+  static thread_local Bm bms[2];
+  Bm &b = bms[slot];
+  if (b.words < words) {
+    free(b.p);
+    b.p = (uint64_t *)calloc(words, sizeof(uint64_t));
+    if (!b.p) throw std::bad_alloc();
+    b.words = words;
+  }
+  return b.p;
+}
+
+// ---------------------------------------------------------------------------
+// Symbolic phase: number of distinct output columns of one group.
+// ---------------------------------------------------------------------------
+template <class K, class IT>
+inline IT sym_group(const IT *acol, IT j0, IT j1, const IT *brpt, const IT *bcol, int64_t ncols,
+                    IT &est, Scratch *&cur, Scratch *&alt) {
+  int64_t flops = 0;
+  for (IT j = j0; j < j1; ++j) {
+    const IT k = acol[j];
+    flops += brpt[k + 1] - brpt[k];
+  }
+  if (flops == 0) return 0;
+  const K EMPTY = ~K(0);
+  const int64_t ub = std::min<int64_t>(flops, ncols);
+  int64_t guess = std::max<int64_t>((int64_t)est + (int64_t)est / 4, 8);
+  if (guess > ub) guess = ub;
+  int lg = std::max(4, ceil_log2((uint64_t)guess * 2));
+  const int lgmax = std::max(4, ceil_log2((uint64_t)ub * 2));
+  if (lg > lgmax) lg = lgmax;
+  size_t S = size_t(1) << lg;
+  K *tab = (K *)cur->get(S * sizeof(K));
+  memset(tab, 0xFF, S * sizeof(K));
+  size_t mask = S - 1;
+  int shift = KeyTraits<K>::bits - lg;
+  size_t lim = (lg < lgmax) ? S / 2 : S;
+  size_t cnt = 0;
+  for (IT j = j0; j < j1; ++j) {
+    const IT k = acol[j];
+    const IT e1 = brpt[k + 1];
+    for (IT e = brpt[k]; e < e1; ++e) {
+      const K key = (K)bcol[e];
+      size_t h = KeyTraits<K>::slot(key, shift);
+      for (;;) {
+        const K t = tab[h];
+        if (t == key) break;
+        if (t == EMPTY) {
+          tab[h] = key;
+          if (++cnt > lim) {
+            int nlg = std::min(lgmax, lg + 2);
+            size_t NS = size_t(1) << nlg;
+            K *nt = (K *)alt->get(NS * sizeof(K));
+            memset(nt, 0xFF, NS * sizeof(K));
+            const int nshift = KeyTraits<K>::bits - nlg;
+            const size_t nmask = NS - 1;
+            for (size_t i = 0; i < S; ++i) {
+              const K x = tab[i];
+              if (x != EMPTY) {
+                size_t hh = KeyTraits<K>::slot(x, nshift);
+                while (nt[hh] != EMPTY) hh = (hh + 1) & nmask;
+                nt[hh] = x;
+              }
+            }
+            std::swap(cur, alt);
+            tab = nt;
+            lg = nlg;
+            S = NS;
+            mask = nmask;
+            shift = nshift;
+            lim = (lg < lgmax) ? S / 2 : S;
+          }
+          break;
+        }
+        h = (h + 1) & mask;
+      }
+    }
+  }
+  est = (IT)cnt;
+  return (IT)cnt;
+}
+
+// Bitmap variant for moderate column counts: one bit per column, branchless
+// test-and-set counting; touched words are recorded for cheap clearing.
+// With LIVE, only "live" paths are counted: the A lane vector of k has a
+// nonzero lane and B[k,c] != 0.  A column reached by no live path is exactly
+// zero in every lane and may be omitted from the output.
+template <bool LIVE, class IT>
+inline IT sym_group_bitmap(const IT *acol, const double *aval, const unsigned char *aalive, IT j0,
+                           IT j1, const IT *brpt, const IT *bcol, const double *bval, uint64_t *bm,
+                           size_t words, Scratch &wl) {
+  int64_t flops = 0;
+  for (IT j = j0; j < j1; ++j) {
+    const IT k = acol[j];
+    flops += brpt[k + 1] - brpt[k];
+  }
+  if (flops == 0) return 0;
+  // Each word is recorded at most once (when it turns nonzero).
+  const size_t twcap = std::min<size_t>((size_t)flops, words);
+  uint32_t *tw = (uint32_t *)wl.get(twcap * sizeof(uint32_t) + 64);
+  size_t nw = 0;
+  int64_t cnt = 0;
+  for (IT j = j0; j < j1; ++j) {
+    const IT k = acol[j];
+    IT e = brpt[k];
+    const IT e1 = brpt[k + 1];
+    if (e == e1) continue;
+    if (LIVE) {
+      bool alive;
+      if (aalive) {
+        alive = aalive[j] != 0;
+      } else {
+        const double *a = aval + (size_t)j * 8;
+        alive = false;
+        for (int l = 0; l < 8; ++l) alive |= (a[l] != 0.0);
+      }
+      if (!alive) continue;
+      for (; e < e1; ++e) {
+        if (!(bval[e] != 0.0)) continue;
+        const uint64_t c = (uint64_t)bcol[e];
+        const uint32_t w = (uint32_t)(c >> 6);
+        const uint64_t bit = uint64_t(1) << (c & 63);
+        const uint64_t old = bm[w];
+        tw[nw] = w;
+        nw += (old == 0);
+        cnt += ((old & bit) == 0);
+        bm[w] = old | bit;
+      }
+      continue;
+    }
+    // Keep the current bitmap word in a register while columns stay in it.
+    uint32_t cw = (uint32_t)((uint64_t)bcol[e] >> 6);
+    uint64_t acc = bm[cw];
+    tw[nw] = cw;
+    nw += (acc == 0);
+    for (; e < e1; ++e) {
+      const uint64_t c = (uint64_t)bcol[e];
+      const uint32_t w = (uint32_t)(c >> 6);
+      if (w != cw) {
+        bm[cw] = acc;
+        cw = w;
+        acc = bm[w];
+        tw[nw] = w;
+        nw += (acc == 0);
+      }
+      const uint64_t bit = uint64_t(1) << (c & 63);
+      cnt += ((acc & bit) == 0);
+      acc |= bit;
+    }
+    bm[cw] = acc;
+  }
+  for (size_t i = 0; i < nw; ++i) bm[tw[i]] = 0;
+  return (IT)cnt;
+}
+
+// ---------------------------------------------------------------------------
+// Numeric phase, width 8 / binary64 / standard multiply-plus fast paths.
+// Table entries pack (key | local_index << 32); keys are 32-bit columns.
+// ---------------------------------------------------------------------------
+inline int table_lg(int64_t cnt) {
+  return std::max(4, ceil_log2((uint64_t)cnt * (cnt > (int64_t(1) << 16) ? 2 : 4)));
+}
+#ifndef FCS_BIG_GROUP
+#define FCS_BIG_GROUP (int64_t(1) << 18)
+#endif
+static const int64_t kBigGroup = FCS_BIG_GROUP;  // accumulate such groups in place
+
+// The SIMD kernels accumulate a group in L1/L2-resident scratch (sc/sv) and
+// then stream the finished group to C with non-temporal stores, avoiding
+// read-for-ownership traffic on the freshly mapped output pages.
+template <bool LIVE, class IT, bool DIRECT = false, bool STREAM = true>
+__attribute__((target("avx512f"))) void num_group_d8_avx512(
+    const IT *acol, const double *aval, IT j0, IT j1, const IT *brpt, const IT *bcol,
+    const double *bval, int64_t cnt, uint64_t *tab, uint32_t *sc, double *sv, uint8_t *lv,
+    IT *oc, double *ov) {
+  if (DIRECT) sv = ov;
+  const int lg = table_lg(cnt);
+  const size_t S = size_t(1) << lg, mask = S - 1;
+  const int shift = 32 - lg;
+  memset(tab, 0xFF, S * sizeof(uint64_t));
+  const __m512d thr = _mm512_set1_pd(kThrD);
+  uint64_t nxt = 0;
+  for (IT j = j0; j < j1; ++j) {
+    const IT k = acol[j];
+    const __m512d a = _mm512_loadu_pd(aval + (size_t)j * 8);
+    const __mmask8 m = _mm512_cmp_pd_mask(_mm512_abs_pd(a), thr, _CMP_GE_OQ);
+    const __m512d am = _mm512_maskz_mov_pd(m, a);
+    const uint8_t alive = LIVE ? (uint8_t)(_mm512_cmp_pd_mask(a, _mm512_setzero_pd(), _CMP_NEQ_UQ) != 0) : 1;
+    const IT e1 = brpt[k + 1];
+    for (IT e = brpt[k]; e < e1; ++e) {
+      const uint32_t key = (uint32_t)bcol[e];
+      const double b = bval[e];
+      const __m512d bv = _mm512_set1_pd(b);
+      size_t h = (uint32_t)(key * 0x9E3779B1u) >> shift;
+      for (;;) {
+        const uint64_t t = tab[h];
+        if ((uint32_t)t == key) {
+          double *p = sv + (t >> 32) * 8;
+          __m512d prod = _mm512_mul_pd(am, bv);
+          __asm__("" : "+v"(prod));  // keep product rounding (no FMA contraction)
+          _mm512_storeu_pd(p, _mm512_add_pd(prod, _mm512_loadu_pd(p)));
+          if (LIVE) lv[t >> 32] |= (uint8_t)(alive & (b != 0.0));
+          break;
+        }
+        if (t == ~uint64_t(0)) {
+          tab[h] = (uint64_t)key | (nxt << 32);
+          if (DIRECT) oc[nxt] = (IT)key;
+          else sc[nxt] = key;
+          _mm512_storeu_pd(sv + nxt * 8, _mm512_mul_pd(a, bv));
+          if (LIVE) lv[nxt] = (uint8_t)(alive & (b != 0.0));
+          ++nxt;
+          break;
+        }
+        h = (h + 1) & mask;
+      }
+    }
+  }
+  if (DIRECT) return;
+  const bool al = STREAM && ((uintptr_t)ov & 63) == 0;
+  if (LIVE) {
+    int64_t o = 0;
+    for (int64_t i = 0; i < (int64_t)nxt; ++i) {
+      if (!lv[i]) continue;
+      if (al) _mm512_stream_pd(ov + o * 8, _mm512_load_pd(sv + i * 8));
+      else _mm512_storeu_pd(ov + o * 8, _mm512_load_pd(sv + i * 8));
+      oc[o] = (IT)sc[i];
+      ++o;
+    }
+    return;
+  }
+  if (al) {
+    for (int64_t i = 0; i < cnt; ++i) _mm512_stream_pd(ov + i * 8, _mm512_load_pd(sv + i * 8));
+  } else {
+    for (int64_t i = 0; i < cnt; ++i) _mm512_storeu_pd(ov + i * 8, _mm512_load_pd(sv + i * 8));
+  }
+  if (STREAM && sizeof(IT) == 8) {
+    for (int64_t i = 0; i < cnt; ++i) _mm_stream_si64((long long *)(oc + i), (long long)sc[i]);
+  } else {
+    for (int64_t i = 0; i < cnt; ++i) oc[i] = (IT)sc[i];
+  }
+}
+
+template <bool LIVE, class IT, bool DIRECT = false, bool STREAM = true>
+__attribute__((target("avx2"))) void num_group_d8_avx2(
+    const IT *acol, const double *aval, IT j0, IT j1, const IT *brpt, const IT *bcol,
+    const double *bval, int64_t cnt, uint64_t *tab, uint32_t *sc, double *sv, uint8_t *lv,
+    IT *oc, double *ov) {
+  if (DIRECT) sv = ov;
+  const int lg = table_lg(cnt);
+  const size_t S = size_t(1) << lg, mask = S - 1;
+  const int shift = 32 - lg;
+  memset(tab, 0xFF, S * sizeof(uint64_t));
+  const __m256d thr = _mm256_set1_pd(kThrD);
+  const __m256d sgn = _mm256_set1_pd(-0.0);
+  uint64_t nxt = 0;
+  for (IT j = j0; j < j1; ++j) {
+    const IT k = acol[j];
+    const __m256d a0 = _mm256_loadu_pd(aval + (size_t)j * 8);
+    const __m256d a1 = _mm256_loadu_pd(aval + (size_t)j * 8 + 4);
+    const __m256d am0 = _mm256_and_pd(_mm256_cmp_pd(_mm256_andnot_pd(sgn, a0), thr, _CMP_GE_OQ), a0);
+    const __m256d am1 = _mm256_and_pd(_mm256_cmp_pd(_mm256_andnot_pd(sgn, a1), thr, _CMP_GE_OQ), a1);
+    uint8_t alive = 1;
+    if (LIVE) {
+      const __m256d z = _mm256_setzero_pd();
+      alive = (uint8_t)((_mm256_movemask_pd(_mm256_cmp_pd(a0, z, _CMP_NEQ_UQ)) |
+                         _mm256_movemask_pd(_mm256_cmp_pd(a1, z, _CMP_NEQ_UQ))) != 0);
+    }
+    const IT e1 = brpt[k + 1];
+    for (IT e = brpt[k]; e < e1; ++e) {
+      const uint32_t key = (uint32_t)bcol[e];
+      const double b = bval[e];
+      const __m256d bv = _mm256_set1_pd(b);
+      size_t h = (uint32_t)(key * 0x9E3779B1u) >> shift;
+      for (;;) {
+        const uint64_t t = tab[h];
+        if ((uint32_t)t == key) {
+          double *p = sv + (t >> 32) * 8;
+          __m256d p0 = _mm256_mul_pd(am0, bv), p1 = _mm256_mul_pd(am1, bv);
+          __asm__("" : "+x"(p0), "+x"(p1));  // keep product rounding (no FMA contraction)
+          _mm256_storeu_pd(p, _mm256_add_pd(p0, _mm256_loadu_pd(p)));
+          _mm256_storeu_pd(p + 4, _mm256_add_pd(p1, _mm256_loadu_pd(p + 4)));
+          if (LIVE) lv[t >> 32] |= (uint8_t)(alive & (b != 0.0));
+          break;
+        }
+        if (t == ~uint64_t(0)) {
+          tab[h] = (uint64_t)key | (nxt << 32);
+          if (DIRECT) oc[nxt] = (IT)key;
+          else sc[nxt] = key;
+          double *p = sv + nxt * 8;
+          _mm256_storeu_pd(p, _mm256_mul_pd(a0, bv));
+          _mm256_storeu_pd(p + 4, _mm256_mul_pd(a1, bv));
+          if (LIVE) lv[nxt] = (uint8_t)(alive & (b != 0.0));
+          ++nxt;
+          break;
+        }
+        h = (h + 1) & mask;
+      }
+    }
+  }
+  if (DIRECT) return;
+  const bool al = STREAM && ((uintptr_t)ov & 31) == 0;
+  if (LIVE) {
+    int64_t o = 0;
+    for (int64_t i = 0; i < (int64_t)nxt; ++i) {
+      if (!lv[i]) continue;
+      if (al) {
+        _mm256_stream_pd(ov + o * 8, _mm256_load_pd(sv + i * 8));
+        _mm256_stream_pd(ov + o * 8 + 4, _mm256_load_pd(sv + i * 8 + 4));
+      } else {
+        _mm256_storeu_pd(ov + o * 8, _mm256_load_pd(sv + i * 8));
+        _mm256_storeu_pd(ov + o * 8 + 4, _mm256_load_pd(sv + i * 8 + 4));
+      }
+      oc[o] = (IT)sc[i];
+      ++o;
+    }
+    return;
+  }
+  if (al) {
+    for (int64_t i = 0; i < cnt; ++i) {
+      _mm256_stream_pd(ov + i * 8, _mm256_load_pd(sv + i * 8));
+      _mm256_stream_pd(ov + i * 8 + 4, _mm256_load_pd(sv + i * 8 + 4));
+    }
+  } else {
+    for (int64_t i = 0; i < cnt; ++i) {
+      _mm256_storeu_pd(ov + i * 8, _mm256_load_pd(sv + i * 8));
+      _mm256_storeu_pd(ov + i * 8 + 4, _mm256_load_pd(sv + i * 8 + 4));
+    }
+  }
+  if (STREAM && sizeof(IT) == 8) {
+    for (int64_t i = 0; i < cnt; ++i) _mm_stream_si64((long long *)(oc + i), (long long)sc[i]);
+  } else {
+    for (int64_t i = 0; i < cnt; ++i) oc[i] = (IT)sc[i];
+  }
+}
+
+template <bool LIVE, class IT>
+void num_group_d8_generic(const IT *acol, const double *aval, IT j0, IT j1, const IT *brpt,
+                          const IT *bcol, const double *bval, int64_t cnt, uint64_t *tab,
+                          uint32_t *sc, double *sv, uint8_t *lv, IT *oc, double *ov) {
+  const int lg = table_lg(cnt);
+  const size_t S = size_t(1) << lg, mask = S - 1;
+  const int shift = 32 - lg;
+  memset(tab, 0xFF, S * sizeof(uint64_t));
+  // Without LIVE, accumulate directly in the output arrays.
+  double *acc = LIVE ? sv : ov;
+  uint64_t nxt = 0;
+  for (IT j = j0; j < j1; ++j) {
+    const IT k = acol[j];
+    double a[8], am[8];
+    uint8_t alive = 0;
+    for (int l = 0; l < 8; ++l) {
+      a[l] = aval[(size_t)j * 8 + l];
+      am[l] = (std::fabs(a[l]) >= kThrD) ? a[l] : 0.0;
+      alive |= (uint8_t)(a[l] != 0.0);
+    }
+    const IT e1 = brpt[k + 1];
+    for (IT e = brpt[k]; e < e1; ++e) {
+      const uint32_t key = (uint32_t)bcol[e];
+      const double bv = bval[e];
+      size_t h = (uint32_t)(key * 0x9E3779B1u) >> shift;
+      for (;;) {
+        const uint64_t t = tab[h];
+        if ((uint32_t)t == key) {
+          double *p = acc + (t >> 32) * 8;
+          for (int l = 0; l < 8; ++l) p[l] = am[l] * bv + p[l];
+          if (LIVE) lv[t >> 32] |= (uint8_t)(alive & (bv != 0.0));
+          break;
+        }
+        if (t == ~uint64_t(0)) {
+          tab[h] = (uint64_t)key | (nxt << 32);
+          if (LIVE) {
+            sc[nxt] = key;
+            lv[nxt] = (uint8_t)(alive & (bv != 0.0));
+          } else {
+            oc[nxt] = (IT)key;
+          }
+          double *p = acc + nxt * 8;
+          for (int l = 0; l < 8; ++l) p[l] = a[l] * bv;
+          ++nxt;
+          break;
+        }
+        h = (h + 1) & mask;
+      }
+    }
+  }
+  if (LIVE) {
+    int64_t o = 0;
+    for (int64_t i = 0; i < (int64_t)nxt; ++i) {
+      if (!lv[i]) continue;
+      for (int l = 0; l < 8; ++l) ov[o * 8 + l] = sv[i * 8 + l];
+      oc[o] = (IT)sc[i];
+      ++o;
+    }
+  }
+}
+
+// ---------------------------------------------------------------------------
+// Numeric phase, general width / value type / operators (exact semantics).
+// ---------------------------------------------------------------------------
+template <class K, class IT, class NT, class MUL, class ADD>
+void num_group_general(const IT *acol, const NT *aval, IT j0, IT j1, const IT *brpt, const IT *bcol,
+                       const NT *bval, int64_t cnt, IT cs, K *tkey, IT *tidx, IT *oc, NT *ov,
+                       const MUL &multop, const ADD &addop) {
+  const K EMPTY = ~K(0);
+  const int lg = table_lg(cnt);
+  const size_t S = size_t(1) << lg, mask = S - 1;
+  const int shift = KeyTraits<K>::bits - lg;
+  for (size_t i = 0; i < S; ++i) tkey[i] = EMPTY;
+  const NT thr = static_cast<NT>(0.000001f);
+  IT nxt = 0;
+  for (IT j = j0; j < j1; ++j) {
+    const IT k = acol[j];
+    const NT *a = aval + (size_t)j * cs;
+    const IT e1 = brpt[k + 1];
+    for (IT e = brpt[k]; e < e1; ++e) {
+      const K key = (K)bcol[e];
+      const NT bv = bval[e];
+      size_t h = KeyTraits<K>::slot(key, shift);
+      for (;;) {
+        const K t = tkey[h];
+        if (t == key) {
+          NT *p = ov + (size_t)tidx[h] * cs;
+          for (IT l = 0; l < cs; ++l) {
+            using std::abs;
+            if (abs(a[l]) >= thr) p[l] = addop(multop(a[l], bv), p[l]);
+          }
+          break;
+        }
+        if (t == EMPTY) {
+          tkey[h] = key;
+          tidx[h] = nxt;
+          oc[nxt] = (IT)key;
+          NT *p = ov + (size_t)nxt * cs;
+          for (IT l = 0; l < cs; ++l) p[l] = multop(a[l], bv);
+          ++nxt;
+          break;
+        }
+        h = (h + 1) & mask;
+      }
+    }
+  }
+}
+
+template <class IT, class NT>
+void sort_group_output(IT *oc, NT *ov, int64_t n, IT cs) {
+  bool sorted = true;
+  for (int64_t i = 1; i < n; ++i)
+    if (oc[i] < oc[i - 1]) {
+      sorted = false;
+      break;
+    }
+  if (sorted) return;
+  std::vector<std::pair<IT, int64_t>> ord((size_t)n);
+  for (int64_t i = 0; i < n; ++i) ord[i] = std::make_pair(oc[i], i);
+  std::sort(ord.begin(), ord.end());
+  std::vector<NT> tmp((size_t)n * cs);
+  for (int64_t i = 0; i < n; ++i) {
+    std::copy(ov + (size_t)ord[i].second * cs, ov + (size_t)ord[i].second * cs + cs, tmp.begin() + (size_t)i * cs);
+    oc[i] = ord[i].first;
+  }
+  std::copy(tmp.begin(), tmp.end(), ov);
+}
+
+template <class MUL, class ADD, class NT>
+struct IsStdArith {
+  static const bool value = std::is_same<NT, double>::value &&
+                            (std::is_same<MUL, std::multiplies<double>>::value ||
+                             std::is_same<MUL, std::multiplies<>>::value) &&
+                            (std::is_same<ADD, std::plus<double>>::value ||
+                             std::is_same<ADD, std::plus<>>::value);
+};
+
+// ---------------------------------------------------------------------------
+// Driver.
+// ---------------------------------------------------------------------------
+template <bool sortOutput, class CF, class CSRB, class MUL, class ADD>
+void cluster_spgemm(const CF &a, const CSRB &b, CF &c, MUL multop, ADD addop) {
+  typedef typename std::remove_pointer<decltype(a.colids)>::type IT;
+  typedef typename std::remove_pointer<decltype(a.values)>::type NT;
+  FCS_T(t0);
+  c.make_empty();
+  const IT cs = a.cluster_sz;
+  const IT ng = a.rows;
+  c.cluster_sz = cs;
+  c.csr_rows = a.csr_rows;
+  c.rows = ng;
+  c.cols = b.cols;
+  c.rowptr = (IT *)mem_alloc(sizeof(IT) * (size_t)(ng + 1), c.mb_rowptr);
+  c.rowptr[0] = 0;
+  const IT *arpt = a.rowptr;
+  const IT *acol = a.colids;
+  const NT *aval = a.values;
+  const IT *brpt = b.rowptr;
+  const IT *bcol = b.colids;
+  const NT *bval = b.values;
+  const int64_t ncols = (int64_t)b.cols;
+  const bool key32 = (ncols >= 0 && ncols < (int64_t)0xFFFFFFFF);
+  const int nt = omp_get_max_threads();
+  const IT chunk = std::max<IT>(8, std::min<IT>(256, ng / ((IT)nt * 64 + 1)) & ~IT(7));
+  const bool fast = IsStdArith<MUL, ADD, NT>::value && cs == 8 && key32;
+#ifndef FCS_BITMAP_MAX_COLS
+#define FCS_BITMAP_MAX_COLS (int64_t(1) << 25)
+#endif
+  const bool use_bitmap = (ncols > 0 && ncols <= (int64_t)(FCS_BITMAP_MAX_COLS));
+  const int isa = detect_isa();
+  const double *avd = reinterpret_cast<const double *>(aval);
+  const double *bvd = reinterpret_cast<const double *>(bval);
+
+  // Work per group (B entries visited) -> scheduling units: groups heavier
+  // than the target run first as their own units (largest first), the rest
+  // in contiguous runs of roughly equal work.
+  std::vector<std::pair<IT, IT>> units;
+  if (ng > 0) {
+    MemBlock mb_w;
+    int64_t *gw = (int64_t *)mem_alloc(sizeof(int64_t) * (size_t)ng, mb_w);
+    int64_t total = 0;
+#pragma omp parallel for schedule(static) reduction(+ : total)
+    for (IT g = 0; g < ng; ++g) {
+      int64_t f = 0;
+      for (IT j = arpt[g]; j < arpt[g + 1]; ++j) {
+        const IT k = acol[j];
+        f += brpt[k + 1] - brpt[k];
+      }
+      f += (arpt[g + 1] - arpt[g]) + 1;
+      gw[g] = f;
+      total += f;
+    }
+    const int64_t target = std::max<int64_t>(total / ((int64_t)nt * 48), 2048);
+    // Each thread cuts its static slice of groups into units independently.
+    std::vector<std::vector<std::pair<IT, IT>>> lt(nt);
+    std::vector<std::vector<std::pair<int64_t, IT>>> ht(nt);
+#pragma omp parallel num_threads(nt)
+    {
+      const int t = omp_get_thread_num(), T = omp_get_num_threads();
+      const IT lo = (IT)((int64_t)ng * t / T), hi = (IT)((int64_t)ng * (t + 1) / T);
+      std::vector<std::pair<IT, IT>> &light = lt[t];
+      std::vector<std::pair<int64_t, IT>> &heavy = ht[t];
+      IT g0 = lo;
+      int64_t acc = 0;
+      for (IT g = lo; g < hi; ++g) {
+        const int64_t f = gw[g];
+        if (f > target) {
+          if (g > g0) light.push_back(std::make_pair(g0, g));
+          heavy.push_back(std::make_pair(f, g));
+          g0 = g + 1;
+          acc = 0;
+          continue;
+        }
+        acc += f;
+        if (acc >= target) {
+          light.push_back(std::make_pair(g0, g + 1));
+          g0 = g + 1;
+          acc = 0;
+        }
+      }
+      if (g0 < hi) light.push_back(std::make_pair(g0, hi));
+    }
+    std::vector<std::pair<int64_t, IT>> heavy;
+    size_t nl = 0;
+    for (int t = 0; t < nt; ++t) {
+      heavy.insert(heavy.end(), ht[t].begin(), ht[t].end());
+      nl += lt[t].size();
+    }
+    std::sort(heavy.begin(), heavy.end(), [](const std::pair<int64_t, IT> &x, const std::pair<int64_t, IT> &y) {
+      return x.first > y.first;
+    });
+    units.reserve(heavy.size() + nl);
+    for (auto &h : heavy) units.push_back(std::make_pair(h.second, h.second + 1));
+    for (int t = 0; t < nt; ++t) units.insert(units.end(), lt[t].begin(), lt[t].end());
+    mem_free(mb_w);
+  }
+  const int64_t nunits = (int64_t)units.size();
+  (void)chunk;
+
+  // Exact zeros (stored zeros of the transformed input) create paths whose
+  // products are zero; when they are common, also count "live" columns.
+  bool dual = false;
+  if (fast && use_bitmap && ng > 0) {
+    int64_t za = a.zero_entries;
+    if (za < 0) {
+      za = 0;
+      const IT an = a.nnzc;
+#pragma omp parallel for schedule(static) reduction(+ : za)
+      for (IT j = 0; j < an; ++j) {
+        bool z = true;
+        for (int l = 0; l < 8; ++l) z &= (avd[(size_t)j * 8 + l] == 0.0);
+        za += z;
+      }
+    }
+    int64_t zb = 0;
+    const IT bn = b.nnz;
+    if (bn > 0) {
+#pragma omp parallel for schedule(static) reduction(+ : zb)
+      for (IT e = 0; e < bn; ++e) zb += (bvd[e] == 0.0);
+    }
+    const double fa = a.nnzc > 0 ? (double)za / (double)a.nnzc : 0.0;
+    const double fb = bn > 0 ? (double)zb / (double)bn : 0.0;
+    dual = (fa >= 0.15 || fb >= 0.15);
+  }
+  MemBlock mb_scnt;
+  IT *scnt = nullptr;  // structural counts (dual mode)
+  if (dual) scnt = (IT *)mem_alloc(sizeof(IT) * (size_t)(ng + 1), mb_scnt);
+
+  // Symbolic.
+  if (ng > 0) {
+#pragma omp parallel
+    {
+      Scratch *cur = &scratch(0), *alt = &scratch(1);
+      IT est = 0;
+      uint64_t *bm = nullptr, *bm2 = nullptr;
+      const size_t words = use_bitmap ? (size_t)((ncols + 63) >> 6) + 1 : 0;
+      if (use_bitmap) {
+        bm = clean_bitmap(0, words);
+        if (dual) bm2 = clean_bitmap(1, words);
+      }
+#pragma omp for schedule(dynamic, 1)
+      for (int64_t u = 0; u < nunits; ++u)
+      for (IT g = units[u].first; g < units[u].second; ++g) {
+        const IT j0 = arpt[g], j1 = arpt[g + 1];
+        IT n = 0, nl = 0;
+        if (j1 > j0) {
+          if (use_bitmap) {
+            n = sym_group_bitmap<false, IT>(acol, avd, nullptr, j0, j1, brpt, bcol, bvd, bm, words, scratch(5));
+            if (dual) nl = sym_group_bitmap<true, IT>(acol, avd, a.alive, j0, j1, brpt, bcol, bvd, bm2, words, scratch(9));
+          } else if (key32) {
+            n = sym_group<uint32_t, IT>(acol, j0, j1, brpt, bcol, ncols, est, cur, alt);
+          } else {
+            n = sym_group<uint64_t, IT>(acol, j0, j1, brpt, bcol, ncols, est, cur, alt);
+          }
+        }
+        if (dual) {
+          scnt[g] = n;
+          c.rowptr[g] = nl;
+        } else {
+          c.rowptr[g] = n;
+        }
+      }
+    }
+  }
+  FCS_T(t1);
+  bool live = false;
+  if (dual) {
+    int64_t st = 0, lt = 0;
+#pragma omp parallel for schedule(static) reduction(+ : st, lt)
+    for (IT g = 0; g < ng; ++g) {
+      st += scnt[g];
+      lt += c.rowptr[g];
+    }
+    live = ((double)lt <= 0.9 * (double)st);
+    if (!live) {
+      std::copy(scnt, scnt + ng, c.rowptr);
+      mem_free(mb_scnt);
+      scnt = nullptr;
+    }
+  }
+  const IT nnzc = (ng > 0) ? exclusive_scan<IT>(c.rowptr, ng) : IT(0);
+  c.nnzc = nnzc;
+  bool reused_c = false, reused_v = false;
+  c.colids = (IT *)mem_alloc(sizeof(IT) * (size_t)std::max<IT>(nnzc, 1), c.mb_colids, &reused_c);
+  c.values = (NT *)mem_alloc(sizeof(NT) * (size_t)std::max<IT>(nnzc, 1) * (size_t)cs, c.mb_values, &reused_v);
+  // Freshly mapped output was just zeroed by the kernel (cache-warm): write it
+  // in place.  Re-used blocks are cold: stream finished groups (no RFO).
+  const bool stream = reused_v;
+  if (nnzc == 0) {
+    mem_free(mb_scnt);
+    return;
+  }
+  FCS_T(t2);
+
+#pragma omp parallel
+  {
+#pragma omp for schedule(dynamic, 1)
+    for (int64_t u = 0; u < nunits; ++u)
+    for (IT g = units[u].first; g < units[u].second; ++g) {
+      const IT o0 = c.rowptr[g], o1 = c.rowptr[g + 1];
+      const int64_t cnt = (int64_t)(o1 - o0);
+      if (cnt == 0) continue;
+      const int64_t tcnt = live ? (int64_t)scnt[g] : cnt;  // structural columns to track
+      const IT j0 = arpt[g], j1 = arpt[g + 1];
+      IT *oc = c.colids + o0;
+      NT *ov = c.values + (size_t)o0 * cs;
+      const size_t S = size_t(1) << table_lg(tcnt);
+      if (fast) {
+        uint64_t *tab = (uint64_t *)scratch(2).get(S * sizeof(uint64_t));
+        double *dv = reinterpret_cast<double *>(ov);
+        uint32_t *sc = nullptr;
+        double *sv = nullptr;
+        uint8_t *lv = nullptr;
+        const bool direct = !live && (tcnt > kBigGroup || !stream);
+        if (!direct && (isa >= ISA_AVX2 || live)) {
+          sc = (uint32_t *)scratch(7).get((size_t)tcnt * sizeof(uint32_t));
+          sv = (double *)scratch(6).get((size_t)tcnt * 8 * sizeof(double));
+        }
+        if (live) lv = (uint8_t *)scratch(10).get((size_t)tcnt);
+        if (direct && isa == ISA_AVX512) {
+          num_group_d8_avx512<false, IT, true>(acol, avd, j0, j1, brpt, bcol, bvd, tcnt, tab, sc, sv, lv, oc, dv);
+        } else if (direct && isa == ISA_AVX2) {
+          num_group_d8_avx2<false, IT, true>(acol, avd, j0, j1, brpt, bcol, bvd, tcnt, tab, sc, sv, lv, oc, dv);
+        } else if (isa == ISA_AVX512) {
+          if (live && stream) num_group_d8_avx512<true, IT, false, true>(acol, avd, j0, j1, brpt, bcol, bvd, tcnt, tab, sc, sv, lv, oc, dv);
+          else if (live) num_group_d8_avx512<true, IT, false, false>(acol, avd, j0, j1, brpt, bcol, bvd, tcnt, tab, sc, sv, lv, oc, dv);
+          else num_group_d8_avx512<false, IT, false, true>(acol, avd, j0, j1, brpt, bcol, bvd, tcnt, tab, sc, sv, lv, oc, dv);
+        } else if (isa == ISA_AVX2) {
+          if (live && stream) num_group_d8_avx2<true, IT, false, true>(acol, avd, j0, j1, brpt, bcol, bvd, tcnt, tab, sc, sv, lv, oc, dv);
+          else if (live) num_group_d8_avx2<true, IT, false, false>(acol, avd, j0, j1, brpt, bcol, bvd, tcnt, tab, sc, sv, lv, oc, dv);
+          else num_group_d8_avx2<false, IT, false, true>(acol, avd, j0, j1, brpt, bcol, bvd, tcnt, tab, sc, sv, lv, oc, dv);
+        } else {
+          if (live) num_group_d8_generic<true, IT>(acol, avd, j0, j1, brpt, bcol, bvd, tcnt, tab, sc, sv, lv, oc, dv);
+          else num_group_d8_generic<false, IT>(acol, avd, j0, j1, brpt, bcol, bvd, tcnt, tab, sc, sv, lv, oc, dv);
+        }
+      } else if (key32) {
+        uint32_t *tk = (uint32_t *)scratch(2).get(S * sizeof(uint32_t));
+        IT *ti = (IT *)scratch(3).get(S * sizeof(IT));
+        num_group_general<uint32_t, IT, NT>(acol, aval, j0, j1, brpt, bcol, bval, cnt, cs, tk, ti, oc, ov, multop, addop);
+      } else {
+        uint64_t *tk = (uint64_t *)scratch(2).get(S * sizeof(uint64_t));
+        IT *ti = (IT *)scratch(3).get(S * sizeof(IT));
+        num_group_general<uint64_t, IT, NT>(acol, aval, j0, j1, brpt, bcol, bval, cnt, cs, tk, ti, oc, ov, multop, addop);
+      }
+      if (sortOutput) sort_group_output<IT, NT>(oc, ov, cnt, cs);
+    }
+    if (fast && isa >= ISA_AVX2) _mm_sfence();  // order streamed output stores
+  }
+  mem_free(mb_scnt);
+#ifdef FCS_PROFILE
+  FCS_T(t3);
+  fprintf(stderr, "  [fcs] sym=%.4f scan+alloc=%.4f num=%.4f nnzc=%ld dual=%d live=%d\n", t1 - t0, t2 - t1, t3 - t2,
+          (long)nnzc, (int)dual, (int)live);
+#endif
+}
+
+}  // namespace fcs
+
+#endif
diff --git a/frontier_solution/fcs_util.h b/frontier_solution/fcs_util.h
new file mode 100644
index 0000000..7eab385
--- /dev/null
+++ b/frontier_solution/fcs_util.h
@@ -0,0 +1,214 @@
+#ifndef FCS_UTIL_H
+#define FCS_UTIL_H
+
+// Shared helpers for the fixed-length clustered SpGEMM path: memory blocks
+// with huge-page advice, ISA dispatch, prefix sums and per-thread scratch.
+
+#include <cstddef>
+#include <cstdint>
+#include <cstdlib>
+#include <cstring>
+#include <new>
+#include <algorithm>
+#include <sys/mman.h>
+#include <mutex>
+#include <omp.h>
+
+namespace fcs {
+
+// ---------------------------------------------------------------------------
+// Memory blocks.  Large arrays are mapped directly (2 MiB aligned, THP advised)
+// so first-touch costs fewer faults; small arrays use posix_memalign.
+// ---------------------------------------------------------------------------
+struct MemBlock {
+  void *base = nullptr;
+  size_t len = 0;  // 0 => malloc'd, otherwise mmap length
+};
+
+static const size_t kHugePage = size_t(1) << 21;
+static const size_t kMapThreshold = size_t(1) << 21;
+
+// Freed large mappings are kept for reuse by later allocations of similar
+// size (repeated products re-use already-faulted pages).
+struct BlockCache {
+  std::mutex mu;
+  MemBlock blk[8];
+  int n = 0;
+  size_t bytes = 0;
+};
+
+inline BlockCache &block_cache() {
+  static BlockCache c;
+  return c;
+}
+
+static const size_t kCacheLimit = size_t(24) << 30;
+
+inline void *mem_alloc(size_t bytes, MemBlock &blk, bool *reused = nullptr) {
+  if (reused) *reused = false;
+  if (bytes == 0) bytes = 64;
+  if (bytes < kMapThreshold) {
+    void *p = nullptr;
+    if (posix_memalign(&p, 64, (bytes + 63) & ~size_t(63)) != 0 || !p) throw std::bad_alloc();
+    blk.base = p;
+    blk.len = 0;
+    return p;
+  }
+  const size_t len = (bytes + kHugePage - 1) & ~(kHugePage - 1);
+  {
+    BlockCache &bc = block_cache();
+    std::lock_guard<std::mutex> lk(bc.mu);
+    int best = -1;
+    for (int i = 0; i < bc.n; ++i)
+      if (bc.blk[i].len >= len && bc.blk[i].len <= len + len / 2 &&
+          (best < 0 || bc.blk[i].len < bc.blk[best].len))
+        best = i;
+    if (best >= 0) {
+      blk = bc.blk[best];
+      bc.bytes -= blk.len;
+      bc.blk[best] = bc.blk[--bc.n];
+      if (reused) *reused = true;
+      return blk.base;
+    }
+  }
+  const size_t maplen = len + kHugePage;
+  void *base = mmap(nullptr, maplen, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
+  if (base == MAP_FAILED) throw std::bad_alloc();
+  const uintptr_t b = (uintptr_t)base;
+  const uintptr_t a = (b + kHugePage - 1) & ~(uintptr_t)(kHugePage - 1);
+  if (a > b) munmap(base, a - b);
+  const uintptr_t e = b + maplen, ae = a + len;
+  if (e > ae) munmap((void *)ae, e - ae);
+#ifdef MADV_HUGEPAGE
+  madvise((void *)a, len, MADV_HUGEPAGE);
+#endif
+  blk.base = (void *)a;
+  blk.len = len;
+  return (void *)a;
+}
+
+inline void mem_free(MemBlock &blk) {
+  if (blk.base) {
+    if (blk.len) {
+      BlockCache &bc = block_cache();
+      bool kept = false;
+      {
+        std::lock_guard<std::mutex> lk(bc.mu);
+        if (bc.n < 8 && bc.bytes + blk.len <= kCacheLimit) {
+          bc.blk[bc.n++] = blk;
+          bc.bytes += blk.len;
+          kept = true;
+        }
+      }
+      if (!kept) munmap(blk.base, blk.len);
+    } else {
+      free(blk.base);
+    }
+  }
+  blk.base = nullptr;
+  blk.len = 0;
+}
+
+// ---------------------------------------------------------------------------
+// ISA dispatch (the build uses baseline x86-64 flags; kernels carry targets).
+// ---------------------------------------------------------------------------
+enum { ISA_GENERIC = 0, ISA_AVX2 = 1, ISA_AVX512 = 2 };
+
+inline int detect_isa() {
+  static int isa = -1;
+  if (isa < 0) {
+    int v = ISA_GENERIC;
+#if defined(__x86_64__) || defined(__i386__)
+    __builtin_cpu_init();
+    if (__builtin_cpu_supports("avx512f")) v = ISA_AVX512;
+    else if (__builtin_cpu_supports("avx2")) v = ISA_AVX2;
+#endif
+    const char *force = getenv("FCS_ISA");
+    if (force && force[0] >= '0' && force[0] <= '2' && force[0] - '0' < v) v = force[0] - '0';
+    isa = v;
+  }
+  return isa;
+}
+
+// ---------------------------------------------------------------------------
+// Small numeric helpers.
+// ---------------------------------------------------------------------------
+inline int ceil_log2(uint64_t x) {
+  int lg = 0;
+  while ((uint64_t(1) << lg) < x) ++lg;
+  return lg;
+}
+
+// In-place exclusive scan of a[0..n); a[n] receives the total.
+template <class T>
+T exclusive_scan(T *a, int64_t n) {
+  if (n <= 0) {
+    a[0] = 0;
+    return 0;
+  }
+  const int nt = omp_get_max_threads();
+  if (n < (int64_t(1) << 16) || nt <= 1) {
+    T s = 0;
+    for (int64_t i = 0; i < n; ++i) {
+      T v = a[i];
+      a[i] = s;
+      s += v;
+    }
+    a[n] = s;
+    return s;
+  }
+  T *part = (T *)alloca(sizeof(T) * (nt + 1));
+  int used = nt;
+#pragma omp parallel num_threads(nt)
+  {
+    const int t = omp_get_thread_num();
+    const int T_ = omp_get_num_threads();
+#pragma omp single
+    used = T_;
+    const int64_t lo = n * t / T_, hi = n * (t + 1) / T_;
+    T s = 0;
+    for (int64_t i = lo; i < hi; ++i) s += a[i];
+    part[t] = s;
+#pragma omp barrier
+    T off = 0;
+    for (int i = 0; i < t; ++i) off += part[i];
+    for (int64_t i = lo; i < hi; ++i) {
+      T v = a[i];
+      a[i] = off;
+      off += v;
+    }
+  }
+  T tot = 0;
+  for (int i = 0; i < used; ++i) tot += part[i];
+  a[n] = tot;
+  return tot;
+}
+
+// ---------------------------------------------------------------------------
+// Grow-only per-thread scratch (persists across calls on pool threads).
+// ---------------------------------------------------------------------------
+struct Scratch {
+  void *p = nullptr;
+  size_t bytes = 0;
+  void *get(size_t need) {
+    if (need > bytes) {
+      free(p);
+      size_t nb = std::max(need, bytes + bytes / 2);
+      nb = (nb + 4095) & ~size_t(4095);
+      p = nullptr;
+      if (posix_memalign(&p, 64, nb) != 0 || !p) throw std::bad_alloc();
+      bytes = nb;
+    }
+    return p;
+  }
+  ~Scratch() { free(p); }
+};
+
+inline Scratch &scratch(int slot) {
+  static thread_local Scratch s[12];
+  return s[slot];
+}
+
+}  // namespace fcs
+
+#endif
